-- bricx.ownership_transfers_guard (ADR 0085, plan K2 b-c): for every role.
-- A transfer's parties, roles and times never change; a settled row never
-- changes again; it is inserted pending. accepted_xact is written here
-- and nowhere else: on the pending -> accepted change it becomes the
-- current transaction's id, and that change passes only when the
-- transaction's user (app.current_user_id()) is the recipient, the row
-- names the recipient as settled_by, and expires_at is still ahead of the
-- transaction's start. Any other value of accepted_xact is refused.
-- SQLSTATE P606C.
CREATE FUNCTION "bricx"."ownership_transfers_guard"() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'pending' OR NEW.accepted_xact IS NOT NULL THEN
      RAISE EXCEPTION 'a transfer starts pending'
        USING ERRCODE = 'P606C';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.initiated_by IS DISTINCT FROM OLD.initiated_by
     OR NEW.to_user_id IS DISTINCT FROM OLD.to_user_id
     OR NEW.previous_owner_role_id IS DISTINCT FROM OLD.previous_owner_role_id
     OR NEW.expires_at IS DISTINCT FROM OLD.expires_at
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'a transfer keeps its terms'
      USING ERRCODE = 'P606C';
  END IF;
  IF OLD.status <> 'pending' THEN
    RAISE EXCEPTION 'a settled transfer is final'
      USING ERRCODE = 'P606C';
  END IF;
  IF NEW.status = 'accepted' THEN
    IF app.current_user_id() IS DISTINCT FROM OLD.to_user_id
       OR NEW.settled_by IS DISTINCT FROM OLD.to_user_id
       OR OLD.expires_at <= transaction_timestamp() THEN
      RAISE EXCEPTION 'only the recipient accepts a live transfer'
        USING ERRCODE = 'P606C';
    END IF;
    NEW.accepted_xact := pg_current_xact_id();
  ELSIF NEW.accepted_xact IS NOT NULL THEN
    RAISE EXCEPTION 'accepted_xact is the guard''s'
      USING ERRCODE = 'P606C';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "ownership_transfers_guard" BEFORE INSERT OR UPDATE ON "bricx"."ownership_transfers" FOR EACH ROW EXECUTE FUNCTION "bricx"."ownership_transfers_guard"();
--> statement-breakpoint
-- bricx.invitation_batches_guard (ADR 0085): for every role. A batch keeps
-- its org, author, size and creation time; a done batch never changes
-- again. SQLSTATE P606D.
CREATE FUNCTION "bricx"."invitation_batches_guard"() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.row_count IS DISTINCT FROM OLD.row_count
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'a batch keeps its identity'
      USING ERRCODE = 'P606D';
  END IF;
  IF OLD.status = 'done' THEN
    RAISE EXCEPTION 'a finished batch is final'
      USING ERRCODE = 'P606D';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "invitation_batches_guard" BEFORE UPDATE ON "bricx"."invitation_batches" FOR EACH ROW EXECUTE FUNCTION "bricx"."invitation_batches_guard"();
--> statement-breakpoint
-- bricx.invitation_batch_rows_guard (ADR 0085): for every role. A row never
-- names the system owner role (an owner comes only from a transfer); its
-- inputs never change; a settled row never changes again; the address
-- changes only to NULL, together with the settlement. SQLSTATE P606D.
CREATE FUNCTION "bricx"."invitation_batch_rows_guard"() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF EXISTS (SELECT 1 FROM bricx.roles r
               WHERE r.org_id = NEW.org_id
                 AND r.id IN (NEW.role_id, NEW.project_role_id)
                 AND r.system_key = 'owner') THEN
      RAISE EXCEPTION 'an owner comes only from a transfer'
        USING ERRCODE = 'P606D';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.batch_id IS DISTINCT FROM OLD.batch_id
     OR NEW.row_no IS DISTINCT FROM OLD.row_no
     OR NEW.role_id IS DISTINCT FROM OLD.role_id
     OR NEW.project_id IS DISTINCT FROM OLD.project_id
     OR NEW.project_role_id IS DISTINCT FROM OLD.project_role_id
     OR NEW.is_external IS DISTINCT FROM OLD.is_external
     OR NEW.membership_expires_at IS DISTINCT FROM OLD.membership_expires_at THEN
    RAISE EXCEPTION 'a batch row keeps its inputs'
      USING ERRCODE = 'P606D';
  END IF;
  IF OLD.status <> 'pending' THEN
    RAISE EXCEPTION 'a settled batch row is final'
      USING ERRCODE = 'P606D';
  END IF;
  IF NEW.email_normalised IS DISTINCT FROM OLD.email_normalised
     AND NOT (NEW.email_normalised IS NULL AND NEW.status <> 'pending') THEN
    RAISE EXCEPTION 'a batch row keeps its address until it settles'
      USING ERRCODE = 'P606D';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "invitation_batch_rows_guard" BEFORE INSERT OR UPDATE ON "bricx"."invitation_batch_rows" FOR EACH ROW EXECUTE FUNCTION "bricx"."invitation_batch_rows_guard"();
