-- bricx.memberships_guard v2 (ADR 0085; amends ADR 0084 D4/D5): every 0014
-- rule unchanged (P606B: is_external is fixed; an owner is never
-- temporary or external), plus two ownership rules (P606C):
-- (a) for EVERY role, the superuser included: a change of role_id to or
--     from the system owner role passes only when this same transaction
--     accepted an ownership transfer of the org (accepted_xact =
--     pg_current_xact_id(), which only ownership_transfers_guard writes)
--     and the change is exactly what that transfer says: the recipient
--     becomes owner, or the initiator gets previous_owner_role_id. No
--     setting, flag or GUC opens it.
-- (d) a new open owner membership (INSERT, or an UPDATE that reopens a
--     removed row) while the org has another open owner membership is
--     refused for every role except the superuser and bricx_owner
--     (owner answer Q7, fail-closed): no request or job can create a
--     second owner; migrations, the bootstrap of an empty organisation
--     and superuser test fixtures can. The row itself is excluded (an
--     INSERT ... ON CONFLICT DO NOTHING of an existing row runs this
--     trigger before the conflict check: the seed's second run).
-- Roles are read as the invoker, as in 0014.
CREATE OR REPLACE FUNCTION "bricx"."memberships_guard"() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER AS $$
DECLARE
  v_key text;
  v_found boolean;
  v_old_key text;
  v_old_found boolean;
  v_privileged boolean;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.is_external IS DISTINCT FROM OLD.is_external THEN
    RAISE EXCEPTION 'a membership keeps its external flag'
      USING ERRCODE = 'P606B';
  END IF;
  SELECT r.system_key, true INTO v_key, v_found
    FROM bricx.roles r WHERE r.org_id = NEW.org_id AND r.id = NEW.role_id;
  IF NEW.is_external OR NEW.expires_at IS NOT NULL THEN
    IF v_found IS NOT TRUE OR v_key = 'owner' THEN
      RAISE EXCEPTION 'an owner is neither temporary nor external'
        USING ERRCODE = 'P606B';
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.role_id IS DISTINCT FROM OLD.role_id THEN
    SELECT r.system_key, true INTO v_old_key, v_old_found
      FROM bricx.roles r WHERE r.org_id = OLD.org_id AND r.id = OLD.role_id;
    -- Fail-closed: a role the invoker cannot see may be the owner role.
    IF (v_found IS NOT TRUE OR v_old_found IS NOT TRUE
        OR v_key = 'owner' OR v_old_key = 'owner') AND NOT EXISTS (
         SELECT 1 FROM bricx.ownership_transfers t
         WHERE t.org_id = NEW.org_id AND t.status = 'accepted'
           AND t.accepted_xact = pg_current_xact_id()
           AND ((NEW.user_id = t.to_user_id AND v_key = 'owner')
             OR (NEW.user_id = t.initiated_by
                 AND NEW.role_id = t.previous_owner_role_id))) THEN
      RAISE EXCEPTION 'ownership changes only by a transfer'
        USING ERRCODE = 'P606C';
    END IF;
  END IF;
  IF (v_key = 'owner' OR v_found IS NOT TRUE) AND NEW.removed_at IS NULL
     AND (TG_OP = 'INSERT' OR OLD.removed_at IS NOT NULL) THEN
    SELECT r.rolsuper OR r.rolname = 'bricx_owner' INTO v_privileged
      FROM pg_catalog.pg_roles r WHERE r.rolname = current_user;
    -- Fail-closed: an unprivileged invoker that cannot see the row's role
    -- is refused as if it were the owner role.
    IF v_privileged IS NOT TRUE AND (v_found IS NOT TRUE OR EXISTS (
         SELECT 1 FROM bricx.memberships m
         JOIN bricx.roles o ON o.org_id = m.org_id AND o.id = m.role_id
         WHERE m.org_id = NEW.org_id AND m.id <> NEW.id
           AND m.removed_at IS NULL AND o.system_key = 'owner')) THEN
      RAISE EXCEPTION 'ownership changes only by a transfer'
        USING ERRCODE = 'P606C';
    END IF;
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
-- app.mfa_transfer_pending(p_user) (ADR 0085): the user is the recipient
-- of a pending transfer that has not expired (database clock). Read inside
-- app.mfa_state() (SECURITY DEFINER as bricx_owner) through the owner
-- read policy.
CREATE FUNCTION "app"."mfa_transfer_pending"(p_user uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SET search_path = pg_catalog, pg_temp
BEGIN ATOMIC
  SELECT EXISTS (
    SELECT 1 FROM bricx.ownership_transfers t
    WHERE t.to_user_id = p_user AND t.status = 'pending'
      AND t.expires_at > now());
END;
--> statement-breakpoint
REVOKE ALL ON FUNCTION "app"."mfa_transfer_pending"(uuid) FROM PUBLIC;
--> statement-breakpoint
-- app.mfa_state() v4 (ADR 0085; amends ADR 0081): v3 (a finance key or an
-- org-admin key) or the recipient of a pending transfer, so the recipient
-- can reach acr mfa before accepting. Same signature, owner, volatility,
-- search_path and grants as 0006/0007/0012 (EXECUTE bricx_relay only);
-- CREATE OR REPLACE keeps them.
CREATE OR REPLACE FUNCTION "app"."mfa_state"(p_user uuid)
RETURNS TABLE (keycloak_sub text, required boolean)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
BEGIN ATOMIC
  SELECT u.keycloak_sub,
    app.mfa_finance_held(u.id) OR app.mfa_admin_held(u.id)
      OR app.mfa_transfer_pending(u.id) AS required
  FROM bricx.users u
  WHERE u.id = p_user;
END;
--> statement-breakpoint
-- app.ownership_transfers_due(p_limit) (ADR 0085): pending transfers past
-- expires_at (database clock), oldest first, at most p_limit (100 at
-- most); the worker expires each one as bricx_app in its org. Writes
-- nothing. SECURITY DEFINER as bricx_owner; EXECUTE for bricx_relay only.
CREATE FUNCTION "app"."ownership_transfers_due"(p_limit integer)
RETURNS TABLE (id uuid, org_id uuid, to_user_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
BEGIN ATOMIC
  SELECT t.id, t.org_id, t.to_user_id
  FROM bricx.ownership_transfers t
  WHERE t.status = 'pending' AND t.expires_at <= now()
  ORDER BY t.expires_at, t.id
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 0), 0), 100);
END;
--> statement-breakpoint
REVOKE ALL ON FUNCTION "app"."ownership_transfers_due"(integer) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION "app"."ownership_transfers_due"(integer) TO bricx_relay;
--> statement-breakpoint
-- app.invitation_batches_stale(p_limit) (ADR 0085, plan K3): batches still
-- queued or running one hour after their creation (database clock),
-- oldest first, at most p_limit (100 at most); the worker settles their
-- pending rows not_processed (address cleared) as bricx_app in the org.
-- SECURITY DEFINER as bricx_owner; EXECUTE for bricx_relay only.
CREATE FUNCTION "app"."invitation_batches_stale"(p_limit integer)
RETURNS TABLE (id uuid, org_id uuid, created_by uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
BEGIN ATOMIC
  SELECT b.id, b.org_id, b.created_by
  FROM bricx.invitation_batches b
  WHERE b.status IN ('queued', 'running')
    AND b.created_at <= now() - interval '1 hour'
  ORDER BY b.created_at, b.id
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 0), 0), 100);
END;
--> statement-breakpoint
REVOKE ALL ON FUNCTION "app"."invitation_batches_stale"(integer) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION "app"."invitation_batches_stale"(integer) TO bricx_relay;
